UPDATE teacher_rules_setting SET version = CASE WHEN content = :content THEN version ELSE version + 1 END, kind = :kind, student = :student, keywords = :keywords, content = :content, once = CAST(:once AS INTEGER), subject_id = CASE WHEN :new_sid = '' THEN subject_id ELSE CAST(:new_sid AS INTEGER) END, author = :author, updated_at = datetime('now', 'localtime') WHERE id = CAST(:id AS INTEGER) AND (subject_id = CAST(:subj AS INTEGER) OR subject_id = 0)
